const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const read=k=>{try{return localStorage.getItem(k)}catch{return null}};
const save=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const osReduced=matchMedia('(prefers-reduced-motion: reduce)');
let manuallyPaused=read('cascade-motion')==='paused',visible=true,raf=0,lastFrame=0,time=0;
const motionButtons=$$('.motion-toggle');
function motionPaused(){return manuallyPaused||osReduced.matches;}
function setMotion(){const paused=motionPaused();document.body.classList.toggle('motion-paused',paused);motionButtons.forEach(b=>{b.setAttribute('aria-pressed',String(paused));b.textContent=paused?(osReduced.matches?'Motion reduced':'Resume motion'):'Pause motion';b.disabled=osReduced.matches;});if(paused){cancelAnimationFrame(raf);raf=0;if(ctx)ctx.clearRect(0,0,canvas.width,canvas.height);}else schedule();}
motionButtons.forEach(b=>b.addEventListener('click',()=>{manuallyPaused=!manuallyPaused;save('cascade-motion',manuallyPaused?'paused':'running');setMotion();}));
osReduced.addEventListener('change',setMotion);
const canvas=$('.wildlife'),hero=$('.hero'),ctx=canvas?.getContext('2d',{alpha:true});
let width=0,height=0,dpr=1;
const birds=new Image(),insects=new Image();birds.src='/assets/birds.webp';insects.src='/assets/insects.webp';
const animals=Array.from({length:8},(_,i)=>newFlight(i));
function newFlight(index){const insect=index>4,fromLeft=Math.random()>.5;const startX=fromLeft?-150:width+150;const endX=fromLeft?width+150:-150;const y=(insect?.55:.18)+Math.random()*(insect?.3:.5);return{index,insect,row:Math.floor(Math.random()*4),startX,endX,y0:y,y1:Math.max(.12,Math.min(.85,y+(Math.random()-.5)*.42)),bend:(Math.random()-.5)*.30,age:Math.random()*12-8,duration:insect?16+Math.random()*9:10+Math.random()*12,size:insect?20+Math.random()*18:28+Math.random()*31,phase:Math.random()*5};}
function resize(){if(!canvas)return;const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx?.setTransform(dpr,0,0,dpr,0,0);animals.forEach((a,i)=>animals[i]=newFlight(i));}
function schedule(){if(canvas&&!raf&&visible&&!document.hidden&&!motionPaused()){lastFrame=0;raf=requestAnimationFrame(paint);}}
function paint(stamp){raf=0;if(!visible||document.hidden||motionPaused())return;if(!lastFrame)lastFrame=stamp;const dt=Math.min((stamp-lastFrame)/1000,.08);if(dt<1/30){raf=requestAnimationFrame(paint);return;}lastFrame=stamp;time+=dt;ctx.clearRect(0,0,width,height);for(let i=0;i<animals.length;i++){let a=animals[i];a.age+=dt;if(a.age<0)continue;let u=a.age/a.duration;if(u>=1){animals[i]=newFlight(i);animals[i].age=-1-Math.random()*6;continue;}const image=a.insect?insects:birds;if(!image.complete||!image.naturalWidth)continue;const e=u*u*(3-2*u);const x=a.startX+(a.endX-a.startX)*e;const y=height*(a.y0+(a.y1-a.y0)*e+Math.sin(u*Math.PI)*a.bend)+Math.sin(time*(a.insect?3:1.3)+a.phase)*(a.insect?12:9);const direction=a.endX>a.startX?1:-1;const scale=.75+.28*Math.sin(u*Math.PI);const size=a.size*scale;const frames=[0,1,2,1],speed=a.insect?16:8+5*(1-Math.sin(u*Math.PI));const frame=frames[Math.floor((time+a.phase)*speed)%4];const cellW=image.naturalWidth/3,cellH=image.naturalHeight/4;ctx.save();ctx.translate(x,y);ctx.scale(direction,1);ctx.rotate(Math.sin(u*Math.PI*2)*.11);ctx.globalAlpha=a.insect?.8:.65+.2*scale;ctx.drawImage(image,frame*cellW,a.row*cellH,cellW,cellH,-size/2,-size*.48,size,size*.96);ctx.restore();}raf=requestAnimationFrame(paint);}
if(hero&&canvas){resize();new ResizeObserver(resize).observe(hero);new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;document.body.classList.toggle('scene-offscreen',!visible);if(!visible){cancelAnimationFrame(raf);raf=0;}else schedule();},{rootMargin:'80px'}).observe(hero);let pointerFrame=0;hero.addEventListener('pointermove',event=>{if(event.pointerType!=='mouse'||motionPaused()||pointerFrame)return;const r=hero.getBoundingClientRect();const x=(event.clientX-r.left)/r.width-.5,y=(event.clientY-r.top)/r.height-.5;pointerFrame=requestAnimationFrame(()=>{hero.style.setProperty('--depth-x',`${x*13}px`);hero.style.setProperty('--depth-y',`${y*9}px`);pointerFrame=0;});});hero.addEventListener('pointerleave',()=>{hero.style.setProperty('--depth-x','0px');hero.style.setProperty('--depth-y','0px');});}
document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('scene-offscreen',document.hidden||!visible);if(document.hidden){cancelAnimationFrame(raf);raf=0;}else schedule();});
setMotion();
// A bounded adjacent-exchange example. State commits immediately; animation never owns it.
const row=$('.demo-row'),status=$('#demo-status');let selected=-1,moves=0,dragSource=-1,dragAt=null;
const start=['circle','square','triangle','diamond'],target=['triangle','circle','square','diamond'];let pieces=[...start];
function renderRow(){if(!row)return;$$('button',row).forEach((b,i)=>{b.dataset.piece=pieces[i];b.setAttribute('aria-label',`${pieces[i]}, position ${i+1}${selected===i?', selected':''}`);b.setAttribute('aria-pressed',String(selected===i));$('.piece',b).className=`piece ${pieces[i]}`;b.setAttribute('aria-disabled',String(pieces.every((p,j)=>p===target[j])));});}
function exchange(a,b){if(Math.abs(a-b)!==1){status.textContent='Choose the neighbouring piece. This little example uses adjacent exchanges.';selected=b;renderRow();return;}const buttons=$$('button',row),before=buttons.map(x=>x.getBoundingClientRect());[pieces[a],pieces[b]]=[pieces[b],pieces[a]];moves++;selected=-1;renderRow();if(!motionPaused())for(const i of [a,b]){const other=i===a?b:a;buttons[i].animate([{transform:`translateX(${before[other].left-before[i].left}px) translateY(-8px)`},{transform:'translateX(0) translateY(0)'}],{duration:310,easing:'cubic-bezier(.16,1,.3,1)'});}if(pieces.every((p,i)=>p===target[i]))measure('puzzle_demo_complete');status.textContent=pieces.every((p,i)=>p===target[i])?`Home, in ${moves} ${moves===1?'exchange':'exchanges'}. In the game, the next platform changes the decision.`:`${moves} ${moves===1?'exchange':'exchanges'}. Bring the triangle to the first position.`;}
function select(i){if(pieces.every((p,j)=>p===target[j]))return;if(selected===i){selected=-1;status.textContent='Selection cancelled.';}else if(selected<0){selected=i;status.textContent='Now choose its neighbour.';}else exchange(selected,i);renderRow();}
if(row){$$('button',row).forEach((b,i)=>{b.addEventListener('click',event=>{if(event.detail===0)select(i);});b.addEventListener('pointerdown',event=>{if(event.button!==0)return;dragSource=i;dragAt={x:event.clientX,y:event.clientY};b.setPointerCapture(event.pointerId);});b.addEventListener('pointerup',event=>{if(dragSource<0)return;const moved=Math.hypot(event.clientX-dragAt.x,event.clientY-dragAt.y)>14;const destination=$$('button',row).findIndex(button=>{const r=button.getBoundingClientRect();return event.clientX>=r.left&&event.clientX<=r.right&&event.clientY>=r.top&&event.clientY<=r.bottom;});const from=dragSource;dragSource=-1;dragAt=null;if(moved&&destination>=0&&destination!==from)exchange(from,destination);else if(!moved)select(from);else{selected=-1;status.textContent='Drag onto the neighbouring piece, or tap two neighbours.';renderRow();}});b.addEventListener('pointercancel',()=>{dragSource=-1;dragAt=null;selected=-1;renderRow();});});$('.demo-reset').addEventListener('click',()=>{pieces=[...start];selected=-1;moves=0;dragSource=-1;renderRow();status.textContent='Two exchanges can bring it home.';});renderRow();}
$$('[data-light]').forEach(b=>b.addEventListener('click',()=>{const night=b.dataset.light==='night';$('.world-section').classList.toggle('night',night);$$('[data-light]').forEach(x=>{const chosen=x===b;x.classList.toggle('selected',chosen);x.setAttribute('aria-pressed',String(chosen));});}));
const cookieDialog=$('#cookie-settings');$$('.cookie-open').forEach(b=>b.addEventListener('click',()=>cookieDialog.showModal()));$('.dialog-close')?.addEventListener('click',()=>cookieDialog.close());cookieDialog?.addEventListener('click',event=>{const r=cookieDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)cookieDialog.close();});
let analyticsLoaded=false,analyticsConfig=null;
async function loadConfig(){try{return await (await fetch('/assets/config.json',{credentials:'same-origin'})).json();}catch{return {analyticsProvider:'none'};}}
function script(src){const s=document.createElement('script');s.async=true;s.src=src;s.dataset.measurement='true';document.head.append(s);}
function disableAnalytics(){const c=analyticsConfig;if(c?.ga4MeasurementId)window['ga-disable-'+c.ga4MeasurementId]=true;window.dataLayer?.push({event:'cascade_consent_revoked',analytics_storage:'denied',ad_storage:'denied'});if(c?.analyticsProvider==='yandex'&&/^\d+$/.test(c.yandexMetricaId))window.ym?.(Number(c.yandexMetricaId),'destruct');document.querySelectorAll('script[data-measurement]').forEach(s=>s.remove());const names=document.cookie.split(';').map(x=>x.split('=')[0].trim()).filter(n=>/^(_ga|_gid|_gat|_ym_|_gcl_)/.test(n));for(const n of names){document.cookie=`${n}=; Max-Age=0; Path=/; SameSite=Lax`;const domain=location.hostname.split('.');for(let i=0;i<domain.length-1;i++)document.cookie=`${n}=; Max-Age=0; Path=/; Domain=.${domain.slice(i).join('.')}; SameSite=Lax`;}}
async function enableAnalytics(){if(analyticsLoaded)return;const c=analyticsConfig=await loadConfig();if(read('cascade-measurement')!=='allow')return;if(c.analyticsProvider==='ga4'&&/^G-[A-Z0-9]+$/.test(c.ga4MeasurementId)){analyticsLoaded=true;window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments);};window.gtag('consent','default',{analytics_storage:'granted',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});window.gtag('js',new Date());window.gtag('config',c.ga4MeasurementId,{allow_google_signals:false,allow_ad_personalization_signals:false});script('https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(c.ga4MeasurementId));}else if(c.analyticsProvider==='gtm'&&/^GTM-[A-Z0-9]+$/.test(c.googleTagManagerId)){analyticsLoaded=true;window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'cascade_measurement_allowed','gtm.start':Date.now(),analytics_storage:'granted',ad_storage:'denied'});script('https://www.googletagmanager.com/gtm.js?id='+encodeURIComponent(c.googleTagManagerId));}else if(c.analyticsProvider==='yandex'&&/^\d+$/.test(c.yandexMetricaId)){analyticsLoaded=true;window.ym=window.ym||function(){(window.ym.a=window.ym.a||[]).push(arguments)};window.ym.l=Date.now();script('https://mc.yandex.ru/metrika/tag.js');window.ym(Number(c.yandexMetricaId),'init',{clickmap:false,trackLinks:false,accurateTrackBounce:true,webvisor:false});}}
$('.cookie-decline')?.addEventListener('click',()=>{save('cascade-measurement','deny');disableAnalytics();cookieDialog.close();if(analyticsLoaded)location.reload();});$('.cookie-accept')?.addEventListener('click',()=>{save('cascade-measurement','allow');cookieDialog.close();enableAnalytics();});
if(read('cascade-measurement')==='allow')enableAnalytics();

const menuButton=document.querySelector(".mobile-menu"),menu=document.querySelector("#site-navigation");
menuButton?.addEventListener("click",()=>{const open=menuButton.getAttribute("aria-expanded")!=="true";menuButton.setAttribute("aria-expanded",String(open));menu.classList.toggle("open",open);});
menu?.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{menu.classList.remove("open");menuButton?.setAttribute("aria-expanded","false");}));
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&menu?.classList.contains("open")){menu.classList.remove("open");menuButton.setAttribute("aria-expanded","false");menuButton.focus();}});
// Optional measurement events carry no save, identity, mail address or puzzle history.
function measure(name){if(!analyticsLoaded||read('cascade-measurement')!=='allow')return;const c=analyticsConfig;if(c.analyticsProvider==='ga4')window.gtag?.('event',name,{page_path:location.pathname});else if(c.analyticsProvider==='gtm')window.dataLayer?.push({event:'cascade_'+name});else if(c.analyticsProvider==='yandex')window.ym?.(Number(c.yandexMetricaId),'reachGoal',name);}
document.querySelectorAll('.store-links a').forEach(a=>a.addEventListener('click',()=>measure('store_visit')));
document.querySelectorAll('a[href^="mailto:"]').forEach(a=>a.addEventListener('click',()=>measure('support_email_start')));
document.querySelectorAll('[data-light]').forEach(b=>b.addEventListener('click',()=>measure('scene_change')));
// Browser-local performance evidence; these values are never sent to a server.
try{new PerformanceObserver(list=>{const entries=list.getEntries();const last=entries[entries.length-1];if(last)document.documentElement.dataset.lcp=String(Math.round(last.startTime));}).observe({type:'largest-contentful-paint',buffered:true});}catch{}
let shiftStart=0,shiftLast=0,shiftSum=0,shiftMaximum=0;
try{new PerformanceObserver(list=>{for(const entry of list.getEntries()){if(entry.hadRecentInput)continue;if(entry.startTime-shiftLast>1000||entry.startTime-shiftStart>5000){shiftStart=entry.startTime;shiftSum=0;}shiftLast=entry.startTime;shiftSum+=entry.value;shiftMaximum=Math.max(shiftMaximum,shiftSum);}document.documentElement.dataset.cls=String(Math.round(shiftMaximum*10000)/10000);}).observe({type:'layout-shift',buffered:true});}catch{}
